// A Node.js adapter can pass readFile from node:fs/promises into this function.
type ReadFile = (path: string, encoding: "utf8") => Promise<string>;
async function readText(readFile: ReadFile, path: string): Promise<string> {
  return readFile(path, "utf8");
}
const demoReadFile: ReadFile = async (path) => `sample contents from ${path}`;
readText(demoReadFile, "notes.txt").then(console.log);
